[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>WellSource — Expert health guidance you can trust</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet">
  <style>
    /* ========== DESIGN SYSTEM TOKENS ========== */
    :root {
      --color-primary: #02838D;
      --color-primary-dark: #016970;
      --color-primary-light: #E0F5F6;
      --color-primary-50: #F0FAFA;
      --color-secondary: #0891B2;
      --color-accent: #E8734A;
      --color-accent-hover: #D4622E;
      --color-bg: #FAFCFB;
      --color-surface: #FFFFFF;
      --color-surface-alt: #F5F8F7;
      --color-text: #231F20;
      --color-text-secondary: #5A6570;
      --color-text-muted: #8A9199;
      --color-border: #E2E8F0;
      --color-border-light: #F0F4F2;
      --color-success: #059669;
      --color-success-light: #ECFDF5;

      --font-heading: 'DM Sans', sans-serif;
      --font-body: 'Inter', sans-serif;

      --shadow-sm: 0 1px 2px rgba(2,131,141,0.06);
      --shadow-md: 0 4px 12px rgba(2,131,141,0.08);
      --shadow-lg: 0 8px 24px rgba(2,131,141,0.1);
      --shadow-xl: 0 12px 40px rgba(2,131,141,0.12);

      --radius-sm: 6px;
      --radius-md: 10px;
      --radius-lg: 16px;
      --radius-xl: 24px;
      --radius-full: 9999px;

      --transition-fast: 150ms ease;
      --transition-base: 200ms ease;
      --transition-slow: 300ms ease;
    }

    /* ========== RESET & BASE ========== */
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }

    body {
      font-family: var(--font-body);
      font-size: 16px;
      line-height: 1.6;
      color: var(--color-text);
      background: var(--color-bg);
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    img { max-width: 100%; display: block; }
    a { color: inherit; text-decoration: none; }
    button { font-family: inherit; cursor: pointer; border: none; background: none; }
    input { font-family: inherit; }
    ul, ol { list-style: none; }

    h1, h2, h3, h4, h5, h6 {
      font-family: var(--font-heading);
      font-weight: 700;
      line-height: 1.2;
    }

    .container {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    @media (min-width: 1440px) {
      .container { max-width: 1360px; }
    }

    /* ========== SKIP LINK ========== */
    .skip-link {
      position: absolute;
      top: -100%;
      left: 16px;
      background: var(--color-primary);
      color: #fff;
      padding: 8px 16px;
      border-radius: var(--radius-sm);
      z-index: 10000;
      font-weight: 600;
    }
    .skip-link:focus { top: 16px; }

    /* ========== HEADER & NAV ========== */
    .header {
      position: sticky;
      top: 0;
      z-index: 1000;
      background: var(--color-surface);
      border-bottom: 1px solid var(--color-border);
      transition: box-shadow var(--transition-base);
    }
    .header.scrolled { box-shadow: var(--shadow-md); }

    .header-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      height: 64px;
    }

    .logo {
      font-family: var(--font-heading);
      font-size: 24px;
      font-weight: 700;
      color: var(--color-primary);
      display: flex;
      align-items: center;
      gap: 8px;
      flex-shrink: 0;
    }
    .logo-icon {
      width: 32px;
      height: 32px;
      background: var(--color-primary);
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .logo-icon svg { width: 18px; height: 18px; }

    .main-nav { display: flex; align-items: center; gap: 4px; height: 100%; }

    .nav-item {
      position: relative;
      height: 100%;
      display: flex;
      align-items: center;
    }

    .nav-link {
      display: flex;
      align-items: center;
      gap: 4px;
      padding: 8px 14px;
      font-size: 14px;
      font-weight: 500;
      color: var(--color-text);
      border-radius: var(--radius-sm);
      transition: color var(--transition-fast), background var(--transition-fast);
      white-space: nowrap;
    }
    .nav-link:hover { color: var(--color-primary); background: var(--color-primary-50); }
    .nav-link svg { width: 14px; height: 14px; transition: transform var(--transition-fast); }
    .nav-item.active .nav-link svg { transform: rotate(180deg); }
    .nav-item.active .nav-link { color: var(--color-primary); }

    /* Mega Menu */
    .mega-menu {
      position: absolute;
      top: 100%;
      left: 50%;
      transform: translateX(-50%);
      min-width: 640px;
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      box-shadow: var(--shadow-xl);
      padding: 24px;
      opacity: 0;
      visibility: hidden;
      transition: opacity var(--transition-base), visibility var(--transition-base);
      pointer-events: none;
    }
    .nav-item.active .mega-menu {
      opacity: 1;
      visibility: visible;
      pointer-events: auto;
    }

    .mega-menu-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 8px;
    }
    .mega-menu-grid.cols-2 { grid-template-columns: repeat(2, 1fr); }

    .mega-link {
      display: block;
      padding: 10px 12px;
      font-size: 14px;
      font-weight: 400;
      color: var(--color-text-secondary);
      border-radius: var(--radius-sm);
      transition: all var(--transition-fast);
    }
    .mega-link:hover {
      background: var(--color-primary-light);
      color: var(--color-primary);
    }

    .mega-section-title {
      font-family: var(--font-heading);
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.08em;
      color: var(--color-text-muted);
      padding: 8px 12px 4px;
      margin-top: 8px;
    }
    .mega-section-title:first-child { margin-top: 0; }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-shrink: 0;
    }

    .btn-subscribe {
      padding: 8px 20px;
      font-size: 13px;
      font-weight: 600;
      color: var(--color-primary);
      border: 1.5px solid var(--color-primary);
      border-radius: var(--radius-full);
      transition: all var(--transition-fast);
    }
    .btn-subscribe:hover { background: var(--color-primary); color: #fff; }

    .btn-signin {
      padding: 8px 20px;
      font-size: 13px;
      font-weight: 600;
      color: #fff;
      background: var(--color-primary);
      border-radius: var(--radius-full);
      transition: all var(--transition-fast);
    }
    .btn-signin:hover { background: var(--color-primary-dark); }

    .mobile-menu-btn {
      display: none;
      width: 44px;
      height: 44px;
      align-items: center;
      justify-content: center;
    }
    .mobile-menu-btn svg { width: 24px; height: 24px; }

    /* ========== CREDIBILITY TICKER ========== */
    .credibility-bar {
      background: var(--color-primary);
      color: #fff;
      overflow: hidden;
      height: 40px;
      position: relative;
    }
    .credibility-bar::before,
    .credibility-bar::after {
      content: '';
      position: absolute;
      top: 0;
      width: 80px;
      height: 100%;
      z-index: 2;
    }
    .credibility-bar::before { left: 0; background: linear-gradient(to right, var(--color-primary), transparent); }
    .credibility-bar::after { right: 0; background: linear-gradient(to left, var(--color-primary), transparent); }

    .ticker-track {
      display: flex;
      align-items: center;
      height: 100%;
      gap: 48px;
      animation: tickerScroll 30s linear infinite;
      width: max-content;
    }
    .ticker-item {
      display: flex;
      align-items: center;
      gap: 8px;
      font-size: 13px;
      font-weight: 500;
      white-space: nowrap;
      flex-shrink: 0;
    }
    .ticker-item svg { width: 16px; height: 16px; flex-shrink: 0; }
    .ticker-separator {
      width: 4px;
      height: 4px;
      background: rgba(255,255,255,0.4);
      border-radius: 50%;
      flex-shrink: 0;
    }

    @keyframes tickerScroll {
      0% { transform: translateX(0); }
      100% { transform: translateX(-50%); }
    }

    @media (prefers-reduced-motion: reduce) {
      .ticker-track { animation: none; }
    }

    /* ========== HERO ========== */
    .hero {
      background: var(--color-surface);
      padding: 48px 0;
    }
    .hero-grid {
      display: grid;
      grid-template-columns: 1fr 380px;
      gap: 32px;
      align-items: start;
    }

    .hero-card {
      position: relative;
      border-radius: var(--radius-lg);
      overflow: hidden;
      aspect-ratio: 16/9;
      background: linear-gradient(135deg, #02838D 0%, #065A60 100%);
      color: #fff;
      display: flex;
      flex-direction: column;
      justify-content: flex-end;
      padding: 40px;
      cursor: pointer;
      transition: transform var(--transition-slow);
    }
    .hero-card:hover { transform: scale(1.005); }
    .hero-card::after {
      content: '';
      position: absolute;
      inset: 0;
      background: linear-gradient(to top, rgba(0,0,0,0.6) 0%, transparent 60%);
    }
    .hero-card > * { position: relative; z-index: 1; }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: var(--color-accent);
      color: #fff;
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      padding: 4px 12px;
      border-radius: var(--radius-full);
      margin-bottom: 12px;
      width: fit-content;
    }
    .hero-badge svg { width: 12px; height: 12px; }

    .hero-title {
      font-size: 32px;
      line-height: 1.15;
      margin-bottom: 8px;
    }
    .hero-subtitle {
      font-size: 15px;
      font-weight: 400;
      opacity: 0.9;
      line-height: 1.5;
    }

    .hero-challenge-tag {
      position: absolute;
      top: 24px;
      right: 24px;
      background: rgba(255,255,255,0.15);
      backdrop-filter: blur(8px);
      border: 1px solid rgba(255,255,255,0.25);
      padding: 8px 16px;
      border-radius: var(--radius-full);
      font-size: 12px;
      font-weight: 600;
      z-index: 1;
      display: flex;
      align-items: center;
      gap: 6px;
    }
    .hero-challenge-tag svg { width: 14px; height: 14px; }

    /* ========== TRENDING SIDEBAR ========== */
    .trending {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      padding: 24px;
    }
    .trending-header {
      font-family: var(--font-heading);
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 20px;
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .trending-header svg { width: 20px; height: 20px; color: var(--color-accent); }

    .trending-list { display: flex; flex-direction: column; gap: 16px; }

    .trending-item {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      padding-bottom: 16px;
      border-bottom: 1px solid var(--color-border-light);
      cursor: pointer;
      transition: opacity var(--transition-fast);
    }
    .trending-item:last-child { border-bottom: none; padding-bottom: 0; }
    .trending-item:hover { opacity: 0.8; }

    .trending-num {
      font-family: var(--font-heading);
      font-size: 24px;
      font-weight: 700;
      color: var(--color-primary);
      line-height: 1;
      min-width: 28px;
    }

    .trending-content { flex: 1; }
    .trending-category {
      font-size: 11px;
      font-weight: 600;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--color-primary);
      margin-bottom: 4px;
    }
    .trending-title {
      font-family: var(--font-heading);
      font-size: 14px;
      font-weight: 600;
      line-height: 1.35;
      color: var(--color-text);
    }

    /* ========== NEWSLETTER CTA ========== */
    .newsletter-cta {
      background: linear-gradient(135deg, var(--color-primary) 0%, #065A60 100%);
      padding: 56px 0;
      color: #fff;
    }
    .newsletter-inner {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 48px;
    }
    .newsletter-text { max-width: 480px; }
    .newsletter-heading {
      font-size: 28px;
      line-height: 1.2;
      margin-bottom: 12px;
    }
    .newsletter-body {
      font-size: 15px;
      opacity: 0.9;
      line-height: 1.6;
    }

    .newsletter-form {
      display: flex;
      gap: 12px;
      flex: 1;
      max-width: 480px;
    }
    .newsletter-input {
      flex: 1;
      padding: 14px 20px;
      border: 2px solid rgba(255,255,255,0.3);
      border-radius: var(--radius-full);
      background: rgba(255,255,255,0.12);
      color: #fff;
      font-size: 14px;
      outline: none;
      transition: border-color var(--transition-fast), background var(--transition-fast);
    }
    .newsletter-input::placeholder { color: rgba(255,255,255,0.6); }
    .newsletter-input:focus { border-color: #fff; background: rgba(255,255,255,0.18); }

    .newsletter-btn {
      padding: 14px 28px;
      background: var(--color-accent);
      color: #fff;
      font-size: 14px;
      font-weight: 700;
      border-radius: var(--radius-full);
      transition: background var(--transition-fast);
      white-space: nowrap;
    }
    .newsletter-btn:hover { background: var(--color-accent-hover); }

    .newsletter-privacy {
      font-size: 12px;
      opacity: 0.7;
      margin-top: 10px;
    }

    /* ========== HEALTH TOPICS CAROUSEL ========== */
    .health-topics {
      padding: 64px 0;
      background: var(--color-surface);
    }

    .section-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
    }
    .section-title {
      font-size: 28px;
      color: var(--color-text);
    }

    .section-nav {
      display: flex;
      gap: 8px;
    }
    .section-nav button {
      width: 40px;
      height: 40px;
      border: 1px solid var(--color-border);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--color-text-secondary);
      transition: all var(--transition-fast);
      background: var(--color-surface);
    }
    .section-nav button:hover {
      border-color: var(--color-primary);
      color: var(--color-primary);
      background: var(--color-primary-light);
    }
    .section-nav button svg { width: 18px; height: 18px; }

    .view-all-link {
      font-size: 14px;
      font-weight: 600;
      color: var(--color-primary);
      display: flex;
      align-items: center;
      gap: 4px;
      transition: gap var(--transition-fast);
    }
    .view-all-link:hover { gap: 8px; }
    .view-all-link svg { width: 14px; height: 14px; }

    .topics-carousel {
      overflow: hidden;
      position: relative;
    }
    .topics-track {
      display: flex;
      gap: 24px;
      transition: transform var(--transition-slow);
    }

    .topic-card {
      flex-shrink: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      cursor: pointer;
      width: 160px;
      text-align: center;
    }
    .topic-card:hover .topic-img { transform: scale(1.05); box-shadow: var(--shadow-lg); }

    .topic-img {
      width: 120px;
      height: 120px;
      border-radius: 50%;
      background: var(--color-primary-light);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition-slow);
      overflow: hidden;
      border: 3px solid var(--color-surface);
      box-shadow: var(--shadow-md);
    }
    .topic-img svg { width: 48px; height: 48px; color: var(--color-primary); }

    .topic-name {
      font-family: var(--font-heading);
      font-size: 14px;
      font-weight: 600;
      color: var(--color-text);
    }

    /* ========== HEALTH TOOLS ========== */
    .health-tools {
      padding: 64px 0;
      background: var(--color-bg);
    }

    .tools-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 32px;
    }

    .tool-section {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      padding: 32px;
    }

    .tool-section-header {
      margin-bottom: 8px;
    }
    .tool-section-heading {
      font-size: 22px;
      margin-bottom: 8px;
    }
    .tool-section-body {
      font-size: 14px;
      color: var(--color-text-secondary);
      line-height: 1.6;
      margin-bottom: 20px;
    }
    .tool-cta {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      font-size: 14px;
      font-weight: 600;
      color: var(--color-primary);
      margin-bottom: 24px;
      transition: gap var(--transition-fast);
    }
    .tool-cta:hover { gap: 10px; }
    .tool-cta svg { width: 16px; height: 16px; }

    .tool-list { display: flex; flex-direction: column; gap: 12px; }

    .tool-item {
      display: flex;
      align-items: center;
      gap: 14px;
      padding: 14px 16px;
      background: var(--color-surface-alt);
      border-radius: var(--radius-md);
      cursor: pointer;
      transition: all var(--transition-fast);
      border: 1px solid transparent;
    }
    .tool-item:hover {
      background: var(--color-primary-light);
      border-color: var(--color-primary);
    }

    .tool-icon {
      width: 40px;
      height: 40px;
      border-radius: var(--radius-sm);
      background: var(--color-primary-light);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
    }
    .tool-icon svg { width: 20px; height: 20px; color: var(--color-primary); }

    .tool-item-content { flex: 1; }
    .tool-item-title {
      font-family: var(--font-heading);
      font-size: 14px;
      font-weight: 600;
      color: var(--color-text);
      margin-bottom: 2px;
    }
    .tool-item-desc {
      font-size: 12px;
      color: var(--color-text-muted);
      line-height: 1.4;
    }

    .tool-item-arrow {
      color: var(--color-text-muted);
      flex-shrink: 0;
      transition: color var(--transition-fast), transform var(--transition-fast);
    }
    .tool-item:hover .tool-item-arrow { color: var(--color-primary); transform: translateX(2px); }
    .tool-item-arrow svg { width: 16px; height: 16px; }

    /* ========== RECOMMENDED READS ========== */
    .recommended-reads {
      padding: 64px 0;
      background: var(--color-surface);
    }

    .reads-tabs {
      display: flex;
      gap: 4px;
      margin-bottom: 32px;
      overflow-x: auto;
      -webkit-overflow-scrolling: touch;
      scrollbar-width: none;
      padding-bottom: 4px;
    }
    .reads-tabs::-webkit-scrollbar { display: none; }

    .reads-tab {
      padding: 10px 20px;
      font-size: 13px;
      font-weight: 600;
      color: var(--color-text-secondary);
      border-radius: var(--radius-full);
      transition: all var(--transition-fast);
      white-space: nowrap;
      border: 1px solid transparent;
    }
    .reads-tab:hover { color: var(--color-primary); background: var(--color-primary-50); }
    .reads-tab.active {
      background: var(--color-primary);
      color: #fff;
    }

    .reads-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 24px;
    }

    .read-card {
      background: var(--color-surface);
      border: 1px solid var(--color-border);
      border-radius: var(--radius-lg);
      overflow: hidden;
      cursor: pointer;
      transition: all var(--transition-slow);
    }
    .read-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-2px);
    }

    .read-card-img {
      width: 100%;
      aspect-ratio: 16/10;
      background: linear-gradient(135deg, var(--color-primary-light) 0%, #C8EAEF 100%);
      position: relative;
      overflow: hidden;
    }
    .read-card-img svg {
      position: absolute;
      bottom: -10px;
      right: -10px;
      width: 80px;
      height: 80px;
      color: var(--color-primary);
      opacity: 0.1;
    }

    .read-card-body { padding: 20px; }
    .read-card-category {
      font-size: 11px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 0.06em;
      color: var(--color-primary);
      margin-bottom: 8px;
    }
    .read-card-title {
      font-family: var(--font-heading);
      font-size: 16px;
      font-weight: 600;
      line-height: 1.35;
      color: var(--color-text);
      margin-bottom: 8px;
    }
    .read-card-meta {
      font-size: 12px;
      color: var(--color-text-muted);
      display: flex;
      align-items: center;
      gap: 8px;
    }
    .read-card-meta svg { width: 12px; height: 12px; }

    /* ========== TRUST SECTION ========== */
    .trust-section {
      padding: 64px 0;
      background: var(--color-primary-50);
    }

    .trust-heading {
      text-align: center;
      font-size: 28px;
      margin-bottom: 48px;
      color: var(--color-text);
    }

    .trust-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .trust-card {
      text-align: center;
      padding: 32px 24px;
      background: var(--color-surface);
      border-radius: var(--radius-lg);
      border: 1px solid var(--color-border);
      transition: all var(--transition-slow);
    }
    .trust-card:hover {
      box-shadow: var(--shadow-md);
      transform: translateY(-2px);
    }

    .trust-icon {
      width: 56px;
      height: 56px;
      background: var(--color-primary-light);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 16px;
    }
    .trust-icon svg { width: 26px; height: 26px; color: var(--color-primary); }

    .trust-card-title {
      font-family: var(--font-heading);
      font-size: 16px;
      font-weight: 700;
      color: var(--color-text);
      margin-bottom: 8px;
    }
    .trust-card-desc {
      font-size: 13px;
      color: var(--color-text-secondary);
      line-height: 1.55;
    }

    /* ========== FEATURED PROGRAMS ========== */
    .featured-programs {
      padding: 64px 0;
      background: var(--color-surface);
    }

    .programs-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .program-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      cursor: pointer;
      transition: all var(--transition-slow);
      border: 1px solid var(--color-border);
    }
    .program-card:hover {
      box-shadow: var(--shadow-lg);
      transform: translateY(-2px);
    }

    .program-img {
      aspect-ratio: 4/3;
      position: relative;
      overflow: hidden;
    }
    .program-img-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .program-img-inner svg { width: 56px; height: 56px; opacity: 0.3; }

    .program-body { padding: 20px; }
    .program-title {
      font-family: var(--font-heading);
      font-size: 15px;
      font-weight: 600;
      color: var(--color-text);
      line-height: 1.35;
    }

    /* ========== LATEST VIDEOS ========== */
    .latest-videos {
      padding: 64px 0;
      background: var(--color-bg);
    }

    .videos-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 24px;
    }

    .video-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      cursor: pointer;
      transition: all var(--transition-slow);
      background: var(--color-surface);
      border: 1px solid var(--color-border);
    }
    .video-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }

    .video-thumb {
      aspect-ratio: 16/9;
      position: relative;
      overflow: hidden;
    }
    .video-thumb-inner {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .video-thumb-inner svg { width: 48px; height: 48px; opacity: 0.2; }

    .play-btn {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 52px;
      height: 52px;
      background: rgba(255,255,255,0.95);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      box-shadow: 0 4px 16px rgba(0,0,0,0.15);
      transition: all var(--transition-fast);
    }
    .video-card:hover .play-btn { background: var(--color-primary); }
    .play-btn svg { width: 20px; height: 20px; color: var(--color-primary); margin-left: 2px; transition: color var(--transition-fast); }
    .video-card:hover .play-btn svg { color: #fff; }

    .video-body { padding: 16px; }
    .video-title {
      font-family: var(--font-heading);
      font-size: 14px;
      font-weight: 600;
      color: var(--color-text);
      line-height: 1.35;
    }

    /* ========== FOOTER ========== */
    .footer {
      background: var(--color-text);
      color: rgba(255,255,255,0.7);
      padding: 56px 0 32px;
    }

    .footer-newsletter {
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 48px;
      padding-bottom: 40px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
      margin-bottom: 40px;
    }
    .footer-newsletter-text { max-width: 440px; }
    .footer-newsletter-heading {
      font-size: 20px;
      font-weight: 700;
      color: #fff;
      margin-bottom: 8px;
    }
    .footer-newsletter-body { font-size: 14px; line-height: 1.6; }

    .footer-form {
      display: flex;
      gap: 12px;
      flex: 1;
      max-width: 440px;
    }
    .footer-input {
      flex: 1;
      padding: 12px 20px;
      border: 1px solid rgba(255,255,255,0.2);
      border-radius: var(--radius-full);
      background: rgba(255,255,255,0.08);
      color: #fff;
      font-size: 14px;
      outline: none;
      transition: border-color var(--transition-fast);
    }
    .footer-input::placeholder { color: rgba(255,255,255,0.4); }
    .footer-input:focus { border-color: rgba(255,255,255,0.5); }

    .footer-btn {
      padding: 12px 24px;
      background: var(--color-primary);
      color: #fff;
      font-size: 13px;
      font-weight: 600;
      border-radius: var(--radius-full);
      transition: background var(--transition-fast);
      white-space: nowrap;
    }
    .footer-btn:hover { background: var(--color-secondary); }

    .footer-links {
      display: flex;
      flex-wrap: wrap;
      gap: 8px 24px;
      margin-bottom: 32px;
    }
    .footer-link {
      font-size: 13px;
      transition: color var(--transition-fast);
    }
    .footer-link:hover { color: #fff; }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: flex-start;
      gap: 24px;
    }
    .footer-legal {
      font-size: 12px;
      line-height: 1.6;
      max-width: 640px;
      opacity: 0.6;
    }
    .footer-social {
      display: flex;
      gap: 16px;
      flex-shrink: 0;
    }
    .social-link {
      width: 36px;
      height: 36px;
      border-radius: 50%;
      border: 1px solid rgba(255,255,255,0.15);
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all var(--transition-fast);
    }
    .social-link:hover { border-color: var(--color-primary); background: var(--color-primary); color: #fff; }
    .social-link svg { width: 16px; height: 16px; }

    /* ========== RESPONSIVE ========== */
    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; }
      .trending { order: -1; }
      .tools-grid { grid-template-columns: 1fr; }
      .trust-grid { grid-template-columns: repeat(2, 1fr); }
      .programs-grid { grid-template-columns: repeat(2, 1fr); }
      .videos-grid { grid-template-columns: repeat(2, 1fr); }
      .reads-grid { grid-template-columns: repeat(2, 1fr); }
    }

    @media (max-width: 768px) {
      .main-nav { display: none; }
      .mobile-menu-btn { display: flex; }
      .header-actions .btn-subscribe { display: none; }

      .hero-card { padding: 28px; aspect-ratio: 16/10; }
      .hero-title { font-size: 24px; }
      .hero-challenge-tag { display: none; }

      .newsletter-inner { flex-direction: column; text-align: center; }
      .newsletter-form { flex-direction: column; max-width: 100%; width: 100%; }

      .reads-grid { grid-template-columns: 1fr; }
      .trust-grid { grid-template-columns: 1fr; }
      .programs-grid { grid-template-columns: 1fr; }
      .videos-grid { grid-template-columns: 1fr; }

      .footer-newsletter { flex-direction: column; text-align: center; }
      .footer-form { flex-direction: column; max-width: 100%; width: 100%; }
      .footer-bottom { flex-direction: column; }

      .section-title { font-size: 22px; }
      .trust-heading { font-size: 22px; }
      .newsletter-heading { font-size: 22px; }
    }

    @media (max-width: 480px) {
      .container { padding: 0 16px; }
      .hero-card { padding: 20px; }
      .hero-title { font-size: 20px; }
      .trending { padding: 16px; }
    }

    /* ========== MOBILE NAV ========== */
    .mobile-nav {
      display: none;
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--color-surface);
      z-index: 9999;
      padding: 24px;
      overflow-y: auto;
    }
    .mobile-nav.open { display: block; }

    .mobile-nav-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      margin-bottom: 32px;
    }
    .mobile-close-btn {
      width: 44px;
      height: 44px;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .mobile-close-btn svg { width: 24px; height: 24px; }

    .mobile-nav-links { display: flex; flex-direction: column; gap: 4px; }
    .mobile-nav-link {
      padding: 14px 16px;
      font-size: 16px;
      font-weight: 600;
      color: var(--color-text);
      border-radius: var(--radius-md);
      transition: background var(--transition-fast);
    }
    .mobile-nav-link:hover { background: var(--color-primary-light); color: var(--color-primary); }
  </style>
</head>
